fn main() {
  panic::set_hook(Box::new(|_| {}));
  let only = std::env::args().nth(1);
  /* a Ray program recurses deeply: a stack of its own */
  let ok = std::thread::Builder::new().stack_size(1 << 30).spawn(move || run(only)).unwrap().join().unwrap_or(false);
  std::process::exit(if ok { 0 } else { 1 });
}
